    ("3.3 Responsabilité des données saisies",
     "3.3 Responsibility for entered data",
     "3.3 Responsabilidad de los datos introducidos",
     "3.3 Verantwortung für die eingegebenen Daten",
     "3.3 Responsabilità dei dati inseriti"),
    ("L'enseignant est responsable des données saisies concernant ses élèves (noms, notes, présences, sanctions). Il s'engage à n'utiliser ProfCalendar que dans le cadre de ses fonctions professionnelles et conformément aux règlements de son établissement.",
     "The teacher is responsible for the data entered about their students (names, grades, attendance, sanctions). They undertake to use ProfCalendar only within the scope of their professional duties and in accordance with their school's regulations.",
     "El docente es responsable de los datos introducidos sobre sus alumnos (nombres, notas, asistencias, sanciones). Se compromete a utilizar ProfCalendar únicamente en el marco de sus funciones profesionales y conforme a la normativa de su centro.",
     "Die Lehrperson ist für die über ihre Schüler eingegebenen Daten (Namen, Noten, Anwesenheiten, Sanktionen) verantwortlich. Sie verpflichtet sich, ProfCalendar nur im Rahmen ihrer beruflichen Tätigkeit und gemäss den Vorschriften ihrer Schule zu nutzen.",
     "L'insegnante è responsabile dei dati inseriti riguardo ai propri studenti (nomi, voti, presenze, sanzioni). Si impegna a utilizzare ProfCalendar solo nell'ambito delle proprie funzioni professionali e nel rispetto dei regolamenti del proprio istituto."),
