    ("Le plan gratuit inclut : tableau de bord, planification de cours, calendrier scolaire et configuration de base. Il est disponible sans limite de durée.",
     "The free plan includes: dashboard, lesson planning, school calendar and basic setup. It is available with no time limit.",
     "El plan gratis incluye: panel de control, planificación de clases, calendario escolar y configuración básica. Está disponible sin límite de tiempo.",
     "Der Gratis-Plan umfasst: Übersicht, Unterrichtsplanung, Schulkalender und Grundkonfiguration. Er ist zeitlich unbegrenzt verfügbar.",
     "Il piano gratuito include: pannello di controllo, pianificazione delle lezioni, calendario scolastico e configurazione di base. È disponibile senza limiti di tempo."),
    ("4.2 Plan Premium",
     "4.2 Premium Plan",
     "4.2 Plan Premium",
     "4.2 Premium-Plan",
     "4.2 Piano Premium"),
    ("Le plan Premium donne accès à l'ensemble des fonctionnalités : gestion de classe, notes et évaluations, suivi des présences, exercices interactifs, collaboration entre enseignants, gestionnaire de fichiers et plan de classe.",
     "The Premium plan gives access to all features: class management, grades and assessments, attendance tracking, interactive exercises, teacher collaboration, file manager and seating plan.",
     "El plan Premium da acceso a todas las funciones: gestión de clase, notas y evaluaciones, control de asistencia, ejercicios interactivos, colaboración entre docentes, gestor de archivos y plano de clase.",
     "Der Premium-Plan gibt Zugang zu allen Funktionen: Klassenverwaltung, Noten und Bewertungen, Anwesenheitskontrolle, interaktive Übungen, Zusammenarbeit unter Lehrpersonen, Dateiverwaltung und Sitzplan.",
     "Il piano Premium dà accesso a tutte le funzionalità: gestione della classe, voti e valutazioni, controllo delle presenze, esercizi interattivi, collaborazione tra insegnanti, gestione file e piantina della classe."),
    ("4.3 Disponibilité",
     "4.3 Availability",
     "4.3 Disponibilidad",
     "4.3 Verfügbarkeit",
     "4.3 Disponibilità"),
    ("ProfCalendar s'efforce de maintenir un accès continu à la plateforme. Toutefois, des interruptions temporaires peuvent survenir pour des raisons de maintenance, de mise à jour ou de force majeure. ProfCalendar ne garantit pas une disponibilité de 100 %%.",
     "ProfCalendar strives to maintain continuous access to the platform. However, temporary interruptions may occur for reasons of maintenance, updates or force majeure. ProfCalendar does not guarantee 100%% availability.",
     "ProfCalendar se esfuerza por mantener un acceso continuo a la plataforma. No obstante, pueden producirse interrupciones temporales por motivos de mantenimiento, actualización o fuerza mayor. ProfCalendar no garantiza una disponibilidad del 100%%.",
     "ProfCalendar ist bestrebt, einen kontinuierlichen Zugang zur Plattform zu gewährleisten. Dennoch können vorübergehende Unterbrechungen aus Gründen der Wartung, von Aktualisierungen oder höherer Gewalt auftreten. ProfCalendar garantiert keine Verfügbarkeit von 100%%.",
     "ProfCalendar si impegna a mantenere un accesso continuo alla piattaforma. Tuttavia, possono verificarsi interruzioni temporanee per ragioni di manutenzione, aggiornamento o forza maggiore. ProfCalendar non garantisce una disponibilità del 100%%."),
