    ("Matière (ex. Maths)", "Subject (e.g. Maths)", "Asignatura (ej. Mates)", "Fach (z. B. Mathe)", "Materia (es. Matematica)"),
    ("Créer mes classes", "Create my classes", "Crear mis clases", "Meine Klassen erstellen", "Crea le mie classi"),
    ("Une autre classe", "Another class", "Otra clase", "Eine weitere Klasse", "Un'altra classe"),
    ("Indiquez au moins un nom de classe et une matière.", "Enter at least one class name and a subject.", "Indica al menos un nombre de clase y una asignatura.", "Geben Sie mindestens einen Klassennamen und ein Fach an.", "Indica almeno un nome di classe e una materia."),
    ("Erreur lors de la création des classes.", "Error while creating the classes.", "Error al crear las clases.", "Fehler beim Erstellen der Klassen.", "Errore durante la creazione delle classi."),
    ("Composez votre horaire", "Build your timetable", "Crea tu horario", "Stellen Sie Ihren Stundenplan zusammen", "Componi il tuo orario"),
    ("Cliquez sur les périodes de votre semaine et choisissez la classe. Validez : vous revenez ici.", "Click the periods of your week and pick the class. Confirm, and you come back here.", "Haz clic en los periodos de tu semana y elige la clase. Confirma y vuelves aquí.", "Klicken Sie auf die Lektionen Ihrer Woche und wählen Sie die Klasse. Bestätigen, und Sie kommen hierher zurück.", "Clicca sui periodi della tua settimana e scegli la classe. Conferma e torni qui."),
    ("Ouvrir l'horaire", "Open the timetable", "Abrir el horario", "Stundenplan öffnen", "Apri l'orario"),
    ("Importez vos vacances", "Import your holidays", "Importa tus vacaciones", "Importieren Sie Ihre Ferien", "Importa le tue vacanze"),
    ("Choisissez votre canton : vacances et jours fériés se placent tout seuls dans le calendrier.", "Pick your canton: holidays and public holidays land in the calendar by themselves.", "Elige tu cantón: las vacaciones y los festivos se colocan solos en el calendario.", "Wählen Sie Ihren Kanton: Ferien und Feiertage landen von selbst im Kalender.", "Scegli il tuo cantone: vacanze e giorni festivi si sistemano da soli nel calendario."),
    ("Canton", "Canton", "Cantón", "Kanton", "Cantone"),
    ("Année scolaire", "School year", "Año escolar", "Schuljahr", "Anno scolastico"),
    ("Importer", "Import", "Importar", "Importieren", "Importa"),
    ("Pas en Suisse romande ? Saisir les vacances à la main", "Not in French-speaking Switzerland? Enter holidays by hand", "¿No estás en la Suiza francófona? Introduce las vacaciones a mano", "Nicht in der Romandie? Ferien von Hand eingeben", "Non sei in Svizzera romanda? Inserisci le vacanze a mano"),
    ('ProfCalendar fonctionne sur abonnement mensuel ou annuel, sans engagement. Consultez notre <a href="/subscription/pricing">page tarifs</a> pour plus de détails.', 'ProfCalendar works on a monthly or annual subscription, with no commitment. See our <a href="/subscription/pricing">pricing page</a> for details.', 'ProfCalendar funciona con una suscripción mensual o anual, sin permanencia. Consulta nuestra <a href="/subscription/pricing">página de precios</a> para más detalles.', 'ProfCalendar funktioniert mit einem monatlichen oder jährlichen Abonnement ohne Bindung. Details finden Sie auf unserer <a href="/subscription/pricing">Preisseite</a>.', 'ProfCalendar funziona con un abbonamento mensile o annuale, senza vincoli. Consulta la nostra <a href="/subscription/pricing">pagina dei prezzi</a> per maggiori dettagli.'),
    ('Configurer mon compte (2 minutes)', 'Set up my account (2 minutes)', 'Configurar mi cuenta (2 minutos)', 'Mein Konto einrichten (2 Minuten)', 'Configura il mio account (2 minuti)'),
    ('Trois étapes guidées : vos classes, votre horaire, vos vacances.', 'Three guided steps: your classes, your timetable, your holidays.', 'Tres pasos guiados: tus clases, tu horario, tus vacaciones.', 'Drei geführte Schritte: Ihre Klassen, Ihr Stundenplan, Ihre Ferien.', 'Tre passaggi guidati: le tue classi, il tuo orario, le tue vacanze.'),
    ('Nouvelle tâche…', 'New task…', 'Nueva tarea…', 'Neue Aufgabe…', 'Nuova attività…'),
    ('Aucune tâche pour le moment.', 'No tasks yet.', 'Ninguna tarea por ahora.', 'Noch keine Aufgaben.', 'Nessuna attività per ora.'),
    ('Suivez cette petite liste : créez vos classes, composez votre horaire, puis importez vos vacances.', 'Follow this short list: create your classes, build your timetable, then import your holidays.', 'Sigue esta pequeña lista: crea tus clases, compón tu horario y luego importa tus vacaciones.', 'Folgen Sie dieser kurzen Liste: Klassen anlegen, Stundenplan zusammenstellen, dann Ferien importieren.', 'Segui questa breve lista: crea le tue classi, componi il tuo orario, poi importa le tue vacanze.'),
    ('Passer', 'Skip', 'Omitir', 'Überspringen', 'Salta'),
    ('Suivant', 'Next', 'Siguiente', 'Weiter', 'Avanti'),
    ('Terminer', 'Finish', 'Terminar', 'Fertig', 'Fine'),
    ('Ce que vous obtenez', 'What you get', 'Lo que obtienes', 'Das erhalten Sie', 'Cosa ottieni'),
    ('Planification et calendrier', 'Planning and calendar', 'Planificación y calendario', 'Planung und Kalender', 'Pianificazione e calendario'),
    ('votre semaine période par période, les vacances de votre canton déjà placées.', "your week period by period, with your canton's holidays already in place.", 'tu semana periodo a periodo, con las vacaciones de tu cantón ya colocadas.', 'Ihre Woche Lektion für Lektion, die Ferien Ihres Kantons bereits eingetragen.', 'la tua settimana periodo per periodo, con le vacanze del tuo cantone già inserite.'),
    ('Page du cours', 'Lesson page', 'Página de la clase', 'Lektionsseite', 'Pagina della lezione'),
    ('présences en un clic, remarques dictées, documents épinglés.', 'one-tap attendance, dictated remarks, pinned documents.', 'asistencia con un toque, observaciones dictadas, documentos fijados.', 'Anwesenheit mit einem Tipp, diktierte Bemerkungen, angeheftete Dokumente.', 'presenze con un tocco, osservazioni dettate, documenti fissati.'),
    ('notes et moyennes automatiques, absences, coches, plan de classe.', 'automatic marks and averages, absences, behaviour tallies, seating plan.', 'notas y medias automáticas, ausencias, marcas, plano de la clase.', 'automatische Noten und Durchschnitte, Absenzen, Strichliste, Sitzplan.', 'voti e medie automatici, assenze, crocette, piano dei posti.'),
    ('stylo, surligneur, règle, compas et équerre en vrais centimètres.', 'pen, highlighter, ruler, compass and set square in real centimetres.', 'bolígrafo, subrayador, regla, compás y escuadra en centímetros reales.', 'Stift, Textmarker, Lineal, Zirkel und Geodreieck in echten Zentimetern.', 'penna, evidenziatore, righello, compasso e squadra in centimetri reali.'),
    ("50 Go pour garder vos documents d'une année à l'autre.", '50 GB to keep your documents from one year to the next.', '50 GB para guardar tus documentos de un curso a otro.', '50 GB, um Ihre Dokumente von Jahr zu Jahr aufzubewahren.', "50 GB per conservare i tuoi documenti da un anno all'altro."),
    ('Prix affiché à l’étape suivante', 'Price shown at the next step', 'Precio indicado en el siguiente paso', 'Preis im nächsten Schritt', 'Prezzo indicato al passaggio successivo'),
    ('Sans engagement', 'Cancel anytime', 'Sin permanencia', 'Jederzeit kündbar', 'Senza vincoli'),
    ('Un seul paiement par an', 'One payment a year', 'Un solo pago al año', 'Eine Zahlung pro Jahr', "Un solo pagamento all'anno"),
    ('Abonnement à renouvellement automatique, résiliable à tout moment dans Réglages > Apple ID > Abonnements, au plus tard 24 heures avant la fin de la période en cours.', 'Auto-renewing subscription. Cancel anytime in Settings > Apple ID > Subscriptions, at least 24 hours before the end of the current period.', 'Suscripción de renovación automática. Cancélala cuando quieras en Ajustes > ID de Apple > Suscripciones, al menos 24 horas antes del final del periodo en curso.', 'Automatisch verlängertes Abonnement. Jederzeit kündbar unter Einstellungen > Apple-ID > Abonnements, spätestens 24 Stunden vor Ende des laufenden Zeitraums.', 'Abbonamento a rinnovo automatico. Disdici quando vuoi in Impostazioni > ID Apple > Abbonamenti, almeno 24 ore prima della fine del periodo in corso.'),
