    ('Chaque période aux couleurs de vos classes, les vacances du canton déjà placées.', "Every period in your classes' colours, with your canton's holidays already in place.", 'Cada periodo con los colores de tus clases y las vacaciones del cantón ya colocadas.', 'Jede Lektion in den Farben Ihrer Klassen, die Ferien des Kantons bereits eingetragen.', 'Ogni periodo con i colori delle tue classi, le vacanze del cantone già inserite.'),
