    ("Ces heures sont proposées par défaut. Vérifiez qu'elles correspondent à votre école avant de placer vos classes.", 'These hours are suggested by default. Check that they match your school before placing your classes.', 'Estas horas se proponen por defecto. Comprueba que corresponden a tu escuela antes de colocar tus clases.', 'Diese Zeiten sind Standardvorschläge. Prüfen Sie, ob sie zu Ihrer Schule passen, bevor Sie Ihre Klassen eintragen.', 'Questi orari sono proposti di default. Verifica che corrispondano alla tua scuola prima di inserire le tue classi.'),
