    ("Sans horaire, la tâche occupe toute la période. Avec, elle s'affichera chaque semaine à ces heures précises dans le calendrier.", 'Without a time, the task takes up the whole period. With one, it will appear every week at those exact times in the calendar.', 'Sin horario, la tarea ocupa todo el período. Con horario, aparecerá cada semana a esas horas exactas en el calendario.', 'Ohne Uhrzeit belegt die Aufgabe die ganze Lektion. Mit Uhrzeit erscheint sie jede Woche genau zu diesen Zeiten im Kalender.', "Senza orario, l'attività occupa tutto il periodo. Con un orario, apparirà ogni settimana a quelle ore precise nel calendario."),
