    ("Votre horaire contient des cours en période {used}, mais ces réglages n'en donnent que {n}. Ces cours ne seront plus affichés. Continuer ?", 'Your timetable has lessons in period {used}, but these settings only produce {n}. Those lessons will no longer be shown. Continue?', 'Tu horario contiene clases en el período {used}, pero estos ajustes solo dan {n}. Esas clases dejarán de mostrarse. ¿Continuar?', 'Ihr Stundenplan enthält Unterricht in Lektion {used}, aber diese Einstellungen ergeben nur {n} Lektionen. Dieser Unterricht wird nicht mehr angezeigt. Fortfahren?', 'Il tuo orario contiene lezioni nel periodo {used}, ma queste impostazioni ne danno solo {n}. Queste lezioni non verranno più mostrate. Continuare?'),
